// NoteView is a note page.
type NoteView struct {
	Note         sqlc.Note
	Blocks       []BlockView
	CanManage    bool
	Visibilities []perm.Visibility
	// Characters are the campaign's characters, for 'listed' audiences.
	Characters  []sqlc.Character
	Backlinks   []sqlc.ListBacklinksRow
	EntityLinks []sqlc.ListEntityFieldBacklinksRow
}

func (v NoteView) characterNames(ids []int64) string {
	var names []string
	for _, c := range v.Characters {
		if slices.Contains(ids, c.ID) {
			names = append(names, c.Name)
		}
	}
	if len(names) == 0 {
		return "nobody yet"
	}
	return strings.Join(names, ", ")
}

func visibilityLabel(vis perm.Visibility) string {
	switch vis {
	case perm.VisGM:
		return "GM only"
	case perm.VisPlayers:
		return "Everyone"
	case perm.VisListed:
		return "Secret"
	case perm.VisOwner:
		return "Private"
	}
	return string(vis)
}

// visTint faintly colours a block's edge and header by visibility, so block
// types stand apart without the colour taking over.
var visTint = map[perm.Visibility]string{
	perm.VisGM:      "border-l-rose-400/60 [&>header]:bg-rose-500/5",
	perm.VisPlayers: "border-l-sky-400/60 [&>header]:bg-sky-500/5",
	perm.VisListed:  "border-l-amber-400/60 [&>header]:bg-amber-500/5",
	perm.VisOwner:   "border-l-violet-400/60 [&>header]:bg-violet-500/5",
}

